tool_input.command:
databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "a832b544eb7dc3fe",
  "wait_timeout": "50s",
  "statement": "CREATE TABLE workspace.mlpabedda14.events385469 (row_id STRING NOT NULL, account_id STRING, event_time BIGINT, amount DOUBLE, category STRING, CONSTRAINT events385469_pk PRIMARY KEY (row_id)) TBLPROPERTIES (delta.enableChangeDataFeed = true)"
}' 2>&1 | head -30

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "a832b544eb7dc3fe",
  "wait_timeout": "50s",
  "statement": "INSERT INTO workspace.mlpabedda14.events385469 SELECT row_id, account_id, CAST(event_time AS BIGINT), CAST(amount AS DOUBLE), category FROM read_files(\"/Volumes/workspace/mlpabedda14/staging/events.csv\", format => \"csv\", header => true, schema => \"row_id STRING, account_id STRING, event_time STRING, amount STRING, category STRING\") WHERE amount IS NOT NULL AND trim(amount) != \"\" AND try_cast(amount AS DOUBLE) IS NOT NULL AND try_cast(amount AS DOUBLE) >= 0 AND try_cast(amount AS DOUBLE) <= 10000 AND category IN (\"grocery\",\"travel\",\"salary\",\"rent\",\"other\")"
}' 2>&1 | head -40

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "a832b544eb7dc3fe",
  "wait_timeout": "50s",
  "statement": "SELECT row_id FROM read_files(\"/Volumes/workspace/mlpabedda14/staging/events.csv\", format => \"csv\", header => true, schema => \"row_id STRING, account_id STRING, event_time STRING, amount STRING, category STRING\") WHERE NOT (amount IS NOT NULL AND trim(amount) != \"\" AND try_cast(amount AS DOUBLE) IS NOT NULL AND try_cast(amount AS DOUBLE) >= 0 AND try_cast(amount AS DOUBLE) <= 10000 AND category IN (\"grocery\",\"travel\",\"salary\",\"rent\",\"other\")) ORDER BY row_id"
}' -o json > .tmp_rejected.json 2>&1; grep -c 'R0' .tmp_rejected.json; head -50 .tmp_rejected.json

databricks online-tables create --json '{
  "name": "workspace.mlpabedda14.events385469_online",
  "spec": {
    "source_table_full_name": "workspace.mlpabedda14.events385469",
    "primary_key_columns": ["row_id"],
    "run_triggered": {}
  }
}' --timeout 25m 2>&1 | tail -30

databricks database create-synced-database-table workspace.mlpabedda14.events385469_online --json '{
  "name": "workspace.mlpabedda14.events385469_online",
  "database_instance_name": "mlpabedda14-store",
  "logical_database_name": "databricks_postgres",
  "spec": {
    "source_table_full_name": "workspace.mlpabedda14.events385469",
    "primary_key_columns": ["row_id"],
    "scheduling_policy": "SNAPSHOT",
    "create_database_objects_if_missing": true
  }
}' 2>&1 | head -40

databricks database create-synced-database-table --json '{
  "name": "workspace.mlpabedda14.events385469_online",
  "database_instance_name": "mlpabedda14-store",
  "logical_database_name": "databricks_postgres",
  "spec": {
    "source_table_full_name": "workspace.mlpabedda14.events385469",
    "primary_key_columns": ["row_id"],
    "scheduling_policy": "SNAPSHOT",
    "create_database_objects_if_missing": true
  }
}' 2>&1 | head -40

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "a832b544eb7dc3fe",
  "wait_timeout": "50s",
  "statement": "SELECT COUNT(*) AS n, MIN(amount), MAX(amount), COUNT(DISTINCT category) FROM workspace.mlpabedda14.events385469"
}' 2>&1 | grep -A8 data_array; rm .tmp_rejected.json
